// Crecimiento, cobertura acumulada, reaparición y Salsa; nunca elimina por masa cero.
GLOMP.minigames = GLOMP.minigames || {};
GLOMP.minigames.eatEm = {
  start: function (w) {
    const c = GLOMP.config.minigames.eatEm;
