    else {
      const sides = [
        { distance: player.x - rectangle.x, nx: -1, ny: 0 },
        { distance: rectangle.x + rectangle.width - player.x, nx: 1, ny: 0 },
        { distance: player.y - rectangle.y, nx: 0, ny: -1 },
