    const mode = GLOMP.minigames.eatEm, c = GLOMP.config.minigames.eatEm;
    w.sauce = w.elapsed < c.sauceStart ? 0 : Math.min(c.maxSauceFraction, c.sauceStep * (1 + Math.floor((w.elapsed - c.sauceStart) / c.sauceInterval)));
