      }
      ui.render(scene); return;
    }
    let id = input.pointerClick; input.pointerClick = null;
    if (ui.pendingSource) {
      if (input.nav) ui.moveFocus(input.nav);
      if (input.confirm) id = ui.focus;
    } else if (room) {
