  pollElapsed: 0,
  gamepadSignature: null,
  diagnostics: { connectedCount: null, indices: [], apiAvailable: false, sixControllersVerified: false },
  onStart: function (scene) {
    if (typeof document !== 'undefined') document.title = GLOMP.i18n.text('bootTitle');
